//! Decision parity for `idfon_voice::turns`: every fixture is generated by running
//! tyger-s2s's rules.py (scripts/tyger-rules-fixtures.py) and must be reproduced
//! exactly here.

use idfon_voice::turns::{Thresholds, TurnSession};
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct FrameIn {
    frames: Vec<(Vec<f32>, f64)>,
    #[serde(default)]
    mode: String,
    #[serde(default)]
    set_words: Option<String>,
    #[serde(default = "level_01")]
    level: f32,
    #[serde(default)]
    agent_level: f32,
}

fn level_01() -> f32 {
    0.1
}

#[derive(Deserialize)]
struct Case {
    name: String,
    th: Thresholds,
    hops: Vec<FrameIn>,
    expected: Value,
}

fn norm(v: &Value) -> String {
    // canonical string form: object key order-insensitive via serde_json's Map ordering
    let mut v = v.clone();
    if let Value::Object(m) = &mut v {
        let keys: Vec<String> = m.keys().cloned().collect();
        let mut sorted = serde_json::Map::new();
        for k in keys {
            sorted.insert(k.clone(), m.remove(&k).unwrap());
        }
        *m = sorted;
    }
    v.to_string()
}

#[test]
fn fixtures_match_the_python_rules() {
    let data = include_str!("data/turns-fixtures.json");
    let cases: Vec<Case> = serde_json::from_str(data).expect("fixtures parse");
    assert!(!cases.is_empty());
    for case in cases {
        let mut sess = TurnSession::new(case.th.clone());
        let exp = &case.expected;
        for (h, hop) in case.hops.iter().enumerate() {
            if let Some(w) = &hop.set_words {
                sess.words = w.clone();
            }
            let user = vec![hop.level; 5120];
            let agent = vec![hop.agent_level; 5120];
            let hr = sess.begin_hop(&user, &agent, &hop.mode);
            let mr = sess.switch_mode(&hop.mode);
            let wv = sess.words_event(&hop.mode).map(|e| serde_json::to_value(&e).unwrap());
            assert_eq!(
                hr,
                exp["hop_reset"][h].as_bool().unwrap(),
                "{} hop {h} begin_hop",
                case.name
            );
            assert_eq!(
                mr,
                exp["mode_changed"][h].as_bool().unwrap(),
                "{} hop {h} switch_mode",
                case.name
            );
            let exp_w = &exp["words_events"][h];
            match (&wv, exp_w) {
                (None, Value::Null) => {}
                (Some(got), _) => assert_eq!(norm(got), norm(exp_w), "{} hop {h} words_event", case.name),
                (None, _) => panic!("{} hop {h}: missing PARTIAL", case.name),
            }
            for (i, (out, act_db)) in hop.frames.iter().enumerate() {
                let left = hop.frames.len() - 1 - i;
                let (events, fin, reset) = sess.on_frame(&hop.mode, out.clone().try_into().unwrap(), *act_db, left);
                let rec = &exp["frame_records"][h][i];
                assert_eq!(reset, rec["reset"].as_bool().unwrap(), "{} hop {h} frame {i} reset", case.name);
                let got: Vec<String> = events
                    .iter()
                    .map(|e| norm(&serde_json::to_value(e).unwrap()))
                    .collect();
                let want: Vec<String> = rec["events"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|e| norm(e))
                    .collect();
                assert_eq!(got, want, "{} hop {h} frame {i} events", case.name);
                if let Some((_ev, audio)) = &fin {
                    assert_eq!(
                        audio.len() as u64,
                        rec["final_turn_len"].as_u64().unwrap(),
                        "{} hop {h} frame {i} final turn len",
                        case.name
                    );
                } else {
                    assert!(rec["final_turn_len"].is_null(), "{} hop {h} frame {i}: unexpected final", case.name);
                }
            }
        }
    }
}
